package com.nexus.web;
import com.nexus.service.*; import com.nexus.domain.*; import com.nexus.domain.Rules.*; import com.nexus.data.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.security.access.AccessDeniedException; import java.time.*; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api") @Transactional public class IncidentController{
 @org.springframework.beans.factory.annotation.Value("${NEXUS_GPS_ENFORCE:false}") private boolean gpsEnforce;
 private final Accounts accounts;private final IncidentService svc;private final NoticeRepository notices;private final Clock clock;
 public IncidentController(Accounts a,IncidentService s,NoticeRepository n,Clock clock){accounts=a;svc=s;notices=n;this.clock=clock;}
 private Account user(Principal p){return accounts.current(p.getName());}
 public record Create(@NotBlank @Size(max=180) String title,@NotBlank @Size(max=8000) String description,@NotNull Long serviceId,@NotNull Long categoryId,@Min(1) @Max(3) int impact,@Min(1) @Max(3) int urgency,String locationCode,@Size(max=100) String locationNote){}
 public record Action(String text,Integer rating,Long technicianId,Long relatedId,Double latitude,Double longitude,Double accuracy){}
 public record GeoInput(Double latitude,Double longitude,Double accuracy){}
 private boolean requireGps(Incident i){return gpsEnforce&&i.locationCode!=null&&CampusCatalog.require(i.locationCode).lat()!=null;}
 @PostMapping("/incidents/{id}/site-check") public GeoCheck.Result siteCheck(Principal p,@PathVariable long id,@RequestBody GeoInput r){Account a=user(p);Incident i=svc.get(id);svc.visible(a,i);if(a.role()!=Role.TECHNICIAN||i.technician==null||!a.id.equals(i.technician.id))throw new AccessDeniedException("Assigned technician only");if(!i.status().active())throw new IllegalArgumentException("Location check is available for active incidents only");if(i.locationCode==null)throw new IllegalArgumentException("No campus site on incident");var result=GeoCheck.check(CampusCatalog.require(i.locationCode),r.latitude(),r.longitude(),r.accuracy());svc.audit().save(new Audit(i.id,clock.instant(),a.name,result.verified()?"LOCATION_CHECK_PASS":"LOCATION_CHECK_FAIL",i.status().name(),i.status().name(),result.reason()+"; approximate site pilot",false));return result;}
 @GetMapping("/catalog") public Map<String,Object> catalog(Principal p){user(p);return Views.map("locations",CampusCatalog.SITES,"services",svc.services().findAll().stream().map(Views::service).toList(),"categories",svc.categories().findAll().stream().map(x -> Views.map("id",x.id,"name",x.name)).toList());}
 @PostMapping("/incidents/preview") public Map<String,Object> preview(Principal p,@Valid @RequestBody Create r){return svc.preview(user(p),r.serviceId(),r.categoryId(),r.impact(),r.urgency(),r.title()+" "+r.description());}
 @PostMapping("/incidents") public Map<String,Object> create(Principal p,@Valid @RequestBody Create r){Account a=user(p);String site=r.locationCode()==null||r.locationCode().isBlank()?null:CampusCatalog.require(r.locationCode()).code(); Incident incident=svc.create(a,r.title(),r.description(),r.serviceId(),r.categoryId(),r.impact(),r.urgency()); incident.locationCode=site; incident.locationNote=site==null?null:r.locationNote(); if(site!=null)svc.audit().save(new Audit(incident.id,clock.instant(),a.name,"LOCATION_RECORDED",incident.status().name(),incident.status().name(),CampusCatalog.require(site).name(),false)); return Views.incident(incident,a.role());}
 @GetMapping("/incidents") public List<Map<String,Object>> list(Principal p,@RequestParam Map<String,String> f){Account a=user(p);return svc.scoped(a).stream().filter(i->matches(i,f)).map(i->Views.incidentSummary(i,a.role())).toList();}
 private boolean matches(Incident i,Map<String,String> f){String q=f.getOrDefault("q","").toLowerCase(Locale.ROOT);return (q.isBlank()||("INC-"+i.id+" "+i.title+" "+i.description).toLowerCase(Locale.ROOT).contains(q))&&eq(f,"status",i.status().name())&&eq(f,"priority",i.priority.name())&&eq(f,"category",i.category.id.toString())&&eq(f,"service",i.service.id.toString())&&eq(f,"technician",i.technician==null?"unassigned":i.technician.id.toString())&&eq(f,"sla",i.responseBreach||i.resolutionBreach?"BREACHED":i.responseWarning||i.resolutionWarning?"WARNING":"OK")&&(!f.containsKey("from")||f.get("from").isBlank()||!i.createdAt.isBefore(LocalDate.parse(f.get("from")).atStartOfDay(ZoneOffset.UTC).toInstant()))&&(!f.containsKey("to")||f.get("to").isBlank()||i.createdAt.isBefore(LocalDate.parse(f.get("to")).plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant()));}
 private boolean eq(Map<String,String> f,String key,String value){return f.getOrDefault(key,"").isBlank()||f.get(key).equalsIgnoreCase(value);}
 @GetMapping("/incidents/{id}") public Map<String,Object> detail(Principal p,@PathVariable long id){Account a=user(p);Incident i=svc.get(id);svc.visible(a,i);var m=Views.incident(i,a.role());m.put("siteVerificationRequired",requireGps(i));m.put("timeline",svc.timeline(a,id));m.put("duplicates",svc.duplicates(a,id));return m;}
 @PostMapping("/incidents/{id}/{action}") public Map<String,Object> action(Principal p,@PathVariable long id,@PathVariable String action,@RequestBody(required=false) Action r){Account a=user(p);if(r==null)r=new Action(null,null,null,null,null,null,null);if(action.equals("resolve")){Incident i=svc.get(id);svc.visible(a,i);if(requireGps(i)){if(a.role()!=Role.TECHNICIAN||i.technician==null||!a.id.equals(i.technician.id))throw new AccessDeniedException("Assigned technician only");var result=GeoCheck.check(CampusCatalog.require(i.locationCode),r.latitude(),r.longitude(),r.accuracy());if(!result.verified())throw new IllegalArgumentException(result.reason());svc.audit().save(new Audit(i.id,clock.instant(),a.name,"LOCATION_CHECK_PASS",i.status().name(),i.status().name(),"Location verified for resolution; pilot radius",false));}}return Views.incident(svc.action(a,id,action,r.text(),r.rating(),r.technicianId(),r.relatedId()),a.role());}
 @GetMapping("/notifications") public List<Notice> notifications(Principal p){return notices.findByRecipientIdOrderByIdDesc(user(p).id);}
 @PostMapping("/notifications/{id}/read") public void read(Principal p,@PathVariable long id){Account a=user(p);Notice n=notices.findById(id).orElseThrow(()->new ApiErrors.Missing("Notification not found"));if(!a.id.equals(n.recipientId))throw new AccessDeniedException("Forbidden");n.opened=true;}
 @PostMapping("/availability") public Map<String,Object> availability(Principal p,@RequestBody Map<String,Boolean> r){Account a=user(p);if(!(a instanceof Technician t))throw new AccessDeniedException("Technician only");if(r.get("available")==null)throw new IllegalArgumentException("Availability required");t.available=r.get("available");return Views.user(t);}
 @GetMapping("/reports") public Map<String,Object> reports(Principal p){Account a=user(p);List<Incident> all=svc.scoped(a);long open=all.stream().filter(i->i.status().active()).count(),critical=all.stream().filter(i->i.status().active()&&i.priority==Priority.P1).count(),breaches=all.stream().filter(i->i.responseBreach||i.resolutionBreach).count(),risk=all.stream().filter(i->i.status().active()&&(Rules.sla(clock.instant(),i.responseDue,i.acknowledgedAt,i.warningMinutes)==Sla.WARNING||Rules.sla(clock.instant(),i.resolutionDue,i.resolvedAt,i.warningMinutes)==Sla.WARNING)).count();long evaluated=0,met=0;for(Incident i:all){if(i.acknowledgedAt!=null||i.responseBreach){evaluated++;if(i.acknowledgedAt!=null&&!i.responseBreach&&!i.acknowledgedAt.isAfter(i.responseDue))met++;}if(i.resolvedAt!=null||i.resolutionBreach){evaluated++;if(i.resolvedAt!=null&&!i.resolutionBreach&&!i.resolvedAt.isAfter(i.resolutionDue))met++;}}return Views.map("total",all.size(),"open",open,"critical",critical,"breaches",breaches,"risk",risk,"compliance",evaluated==0?null:Math.round(100.0*met/evaluated),"evaluatedTargets",evaluated,"incidents",all.stream().map(i->Views.incidentSummary(i,a.role())).toList());}
}
